       await Promise.resolve();
     });

     expect(screen.getByLabelText("Label date")).toHaveValue("2027-01-01");
     expect(screen.getByLabelText("Label time")).toHaveValue("00:00");

     await act(() => {
       root?.unmount();
     });
     vi.unstubAllGlobals();

     expect(screen.queryByLabelText("Label date")).toBeNull();
   });

